class FraudGridScanner {

    private static final Logger log = Logger.getLogger(FraudGridScanner.class.getName());

    int countRings(char[][] grid) {
        if (grid.length == 0) return 0;
        int rings = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '1') {       // unvisited flagged cell
                    rings++;
                    final int rr = r, cc = c;
                    log.fine(() -> "  new ring starting at (" + rr + "," + cc + ")");
                    sink(grid, r, c);          // flood fill the whole blob
                }
            }
        }
        return rings;
    }

    // Depth-first flood fill: mark visited by overwriting with '0'.
    private void sink(char[][] grid, int r, int c) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length || grid[r][c] != '1') {
            return;                            // out of bounds or not flagged
        }
        grid[r][c] = '0';                      // mark visited
        sink(grid, r - 1, c);                  // up
        sink(grid, r + 1, c);                  // down
        sink(grid, r, c - 1);                  // left
        sink(grid, r, c + 1);                  // right
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
